import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, issueInvoice, applyVoucher } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';
import { renderInvoiceText } from '../src/render.js';

test('renderInvoiceText renders a draft invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 0 },
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 0 },
    ],
  });

  const result = renderInvoiceText(invoiceResult.value);
  assert.equal(result.ok, true);

  const text = result.value;
  assert.match(text, /^DRAFT\n/);
  assert.match(text, /^DRAFT\nNorthwind Studio\n/);
  assert.match(text, /5 Design work \(hour\) €85\.00 €425\.00/);
  assert.match(text, /1 Logo package €1,200\.00 €1,200\.00/);
  assert.match(text, /VAT: €341\.25\n/);
  assert.match(text, /Total: €1,966\.25/);
});

test('renderInvoiceText renders an issued invoice with number', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 0 }],
  });

  const issueResult = issueInvoice(invoiceResult.value, []);
  const result = renderInvoiceText(issueResult.value);

  assert.equal(result.ok, true);
  const text = result.value;
  assert.match(text, /^INV-2026-0001\n/);
  // Subtotal: 2 * 8500 = 17000, VAT = 17000 * 0.21 = 3570, Total = 20570
  assert.match(text, /VAT: €35\.70\n/);
  assert.match(text, /Total: €205\.70/);
});

test('renderInvoiceText handles multiple line items', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 3 },
      { sku: 'DEV-HOUR', qty: 2 },
      { sku: 'COPY-HOUR', qty: 1 },
    ],
  });

  const result = renderInvoiceText(invoiceResult.value);
  assert.equal(result.ok, true);

  const text = result.value;
  assert.match(text, /Blue Fern Bakery/);
  assert.match(text, /3 Design work \(hour\) €85\.00 €255\.00/);
  assert.match(text, /2 Development \(hour\) €95\.00 €190\.00/);
  assert.match(text, /1 Copywriting \(hour\) €60\.00 €60\.00/);
  // Subtotal: 255 + 190 + 60 = 50500 cents = €505.00
  // VAT: 50500 * 0.21 = 10605 cents = €106.05
  // Total: 50500 + 10605 = 61105 cents = €611.05
  assert.match(text, /VAT: €106\.05\n/);
  assert.match(text, /Total: €611\.05$/);
});

test('renderInvoiceText formats amounts with euro currency', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'ICON-SET', qty: 100 }],
  });

  const result = renderInvoiceText(invoiceResult.value);
  const text = result.value;

  // ICON-SET is 980 cents = €9.80
  // 100 × €9.80 = €980.00
  assert.match(text, /€9\.80/);
  assert.match(text, /€980\.00/);
});

test('renderInvoiceText uses customer name from database', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-007',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const result = renderInvoiceText(invoiceResult.value);
  const text = result.value;
  assert.match(text, /Halvorsen Architects/);
});

test('renderInvoiceText reports unknown customer', () => {
  const invoice = {
    customerId: 'C-999',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 1, unitPrice: 8500, vatRate: 21 }],
  };

  assert.deepEqual(
    renderInvoiceText(invoice),
    { ok: false, error: 'CUSTOMER_NOT_FOUND' }
  );
});

test('renderInvoiceText includes blank lines for readability', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const result = renderInvoiceText(invoiceResult.value);
  const text = result.value;
  const lines = text.split('\n');

  // Should have: number, customer, blank, item, blank, total = 6 lines minimum
  assert.ok(lines.length >= 6);
  assert.equal(lines[2], ''); // Blank line after customer
});

test('renderInvoiceText with large quantities and prices', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-008',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'BRAND-BOOK', qty: 3, discountPercent: 0 },
      { sku: 'WORKSHOP-DAY', qty: 2, discountPercent: 0 },
    ],
  });

  const result = renderInvoiceText(invoiceResult.value);
  const text = result.value;

  // BRAND-BOOK: qty 3 × €2,450.00 = €7,350.00, VAT 9%
  // After 5% tier discount: €6,982.50, VAT: €628.43
  // WORKSHOP-DAY: qty 2 × €600.00 = €1,200.00, VAT 0%
  // After 5% tier discount: €1,140.00, VAT: €0.00
  // Subtotal: €8,550.00
  // Total discount: €427.50
  // Total VAT: €628.43
  // Total: €8,750.93
  assert.match(text, /€2,450\.00/);
  assert.match(text, /€7,350\.00/);
  assert.match(text, /€600\.00/);
  assert.match(text, /€1,200\.00/);
  assert.match(text, /VAT:/);
  assert.match(text, /Total:/);
});

test('renderInvoiceText shows line discounts', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 10 },
    ],
  });

  const result = renderInvoiceText(invoiceResult.value);
  const text = result.value;

  // Should show the discount
  assert.match(text, /Discount \(10%\):/);
  assert.match(text, /Discount \(10%\): -€42\.50/);
});

test('renderInvoiceText does not show zero discounts', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 0 },
    ],
  });

  const result = renderInvoiceText(invoiceResult.value);
  const text = result.value;

  // Should not show discount for 0%
  assert.ok(!text.includes('Discount (0%)'));
});

test('renderInvoiceText shows multiple line discounts', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 10 },
      { sku: 'DEV-HOUR', qty: 3, discountPercent: 5 },
