test('renderInvoiceText shows voucher', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const withVoucher = applyVoucher(invoiceResult.value, {
    code: 'SUMMER2026',
    amount: 10000,
  }).value;

  const result = renderInvoiceText(withVoucher);
  const text = result.value;

  assert.match(text, /Voucher \(SUMMER2026\): -€100\.00/);
  // Voucher should appear before VAT/Total
  assert.ok(text.indexOf('Voucher') < text.indexOf('VAT'));
});

test('renderInvoiceText does not show voucher when absent', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const result = renderInvoiceText(invoiceResult.value);
  const text = result.value;

  assert.ok(!text.includes('Voucher'));
});

test('renderInvoiceText shows due date for issued invoices', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });

  const issued = issueInvoice(invoiceResult.value, []).value;
  const result = renderInvoiceText(issued);
  const text = result.value;

  // Due date should be 2026-10-21 (14 days after 2026-10-07)
  assert.match(text, /Due: 2026-10-21/);
});

test('renderInvoiceText shows due date even for draft invoices', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const result = renderInvoiceText(invoiceResult.value);
  const text = result.value;

  // Draft invoices have a dueDate calculated (NET30 by default = 2026-11-06)
  assert.match(text, /Due: 2026-11-06/);
});

test('renderInvoiceText shows paid amount', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const issued = issueInvoice(invoiceResult.value, []).value;
  const paid = recordPayment(issued, { amount: 20000, date: '2026-10-10' }).value;

  const result = renderInvoiceText(paid);
  const text = result.value;

  assert.match(text, /Paid: €200\.00/);
});

test('renderInvoiceText does not show paid when no payments', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const issued = issueInvoice(invoiceResult.value, []).value;
  const result = renderInvoiceText(issued);
  const text = result.value;

  assert.ok(!text.includes('Paid:'));
});

test('renderInvoiceText shows multiple payments combined', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const issued = issueInvoice(invoiceResult.value, []).value;
  const paid1 = recordPayment(issued, { amount: 10000, date: '2026-10-10' }).value;
  const paid2 = recordPayment(paid1, { amount: 10000, date: '2026-10-15' }).value;

  const result = renderInvoiceText(paid2);
  const text = result.value;

  // Should show total of both payments
  assert.match(text, /Paid: €200\.00/);
});

test('renderInvoiceText with all features', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10, discountPercent: 5 },
      { sku: 'LOGO-PACK', qty: 2, discountPercent: 0 },
    ],
    terms: 'NET30',
  });

  let invoice = applyVoucher(invoiceResult.value, {
    code: 'WELCOME',
    amount: 5000,
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const paid = recordPayment(issued, { amount: 30000, date: '2026-10-15' }).value;

  const result = renderInvoiceText(paid);
  const text = result.value;

  // Check all features are present
  assert.match(text, /^INV-2026-0001\n/);
  assert.match(text, /Northwind Studio/);
  assert.match(text, /10 Design work \(hour\) €85\.00 €850\.00/);
  assert.match(text, /Discount \(5%\):/);
  assert.match(text, /2 Logo package €1,200\.00 €2,400\.00/);
  assert.match(text, /Voucher \(WELCOME\): -€50\.00/);
  assert.match(text, /VAT:/);
  assert.match(text, /Total:/);
  assert.match(text, /Due: 2026-11-06/);
  assert.match(text, /Paid: €300\.00/);
});

test('renderInvoiceText with bulk discount', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10, discountPercent: 0 },
    ],
  });

  const result = renderInvoiceText(invoiceResult.value);
  const text = result.value;

  // Should show line item but no discount line (since discountPercent is 0, bulk discount is separate)
  assert.match(text, /10 Design work \(hour\) €85\.00 €850\.00/);
  assert.ok(!text.includes('Discount (0%)'));
});

test('renderInvoiceText orders lines correctly', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 10 },
    ],
    terms: 'NET14',
  });

  let invoice = applyVoucher(invoiceResult.value, {
    code: 'TEST',
    amount: 5000,
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const paid = recordPayment(issued, { amount: 10000, date: '2026-10-10' }).value;

  const result = renderInvoiceText(paid);
  const text = result.value;
  const lines = text.split('\n');

  // Order should be: number, customer, blank, items (with discounts), blank, voucher, VAT, total, due, paid
  const textParts = {
    invoiceNumber: lines.findIndex(l => l === 'INV-2026-0001'),
    customer: lines.findIndex(l => l === 'Northwind Studio'),
    discount: lines.findIndex(l => l.includes('Discount')),
    voucher: lines.findIndex(l => l.includes('Voucher')),
    vat: lines.findIndex(l => l.includes('VAT')),
    total: lines.findIndex(l => l.includes('Total:')),
    due: lines.findIndex(l => l.includes('Due:')),
    paid: lines.findIndex(l => l.includes('Paid:')),
  };

  // Verify order
  assert.ok(textParts.invoiceNumber < textParts.customer);
  assert.ok(textParts.customer < textParts.discount);
  assert.ok(textParts.discount < textParts.voucher);
  assert.ok(textParts.voucher < textParts.vat);
  assert.ok(textParts.vat < textParts.total);
  assert.ok(textParts.total < textParts.due);
  assert.ok(textParts.due < textParts.paid);
});
